import {loadModel} from './model.mjs';
// At most one transferred frame. No inference queue can accumulate behind the live camera.
export class Detector{
 static async create(){const d=new Detector();if(typeof Worker!=='undefined'&&typeof createImageBitmap==='function')try{await d.initWorker();return d}catch{d.worker?.terminate();d.worker=null}d.model=await loadModel();return d}
 initWorker(){return new Promise((resolve,reject)=>{this.worker=new Worker(new URL('./tracker-worker.mjs',import.meta.url),{type:'module'});const timeout=setTimeout(()=>reject(Error('Worker init timeout')),25000);this.worker.onerror=()=>{clearTimeout(timeout);if(this.pending){clearTimeout(this.pending.timer);this.pending.reject(Error('Worker stopped'));this.pending=null}else reject(Error('Worker unavailable'))};this.worker.onmessage=({data})=>{if(data.type==='ready'){clearTimeout(timeout);resolve()}else if(data.id&&this.pending?.id===data.id){const p=this.pending;this.pending=null;clearTimeout(p.timer);data.type==='result'?p.resolve(data.result):p.reject(Error(data.error))}else if(data.type==='error'){clearTimeout(timeout);reject(Error(data.error))}};this.worker.postMessage({type:'init'})})}
 async detect(video,timestamp){if(this.busy)throw Error('Inference already in flight');this.busy=true;try{if(!this.worker)return this.model.detectForVideo(video,timestamp);const ratio=Math.min(1,(this.maxWidth||640)/video.videoWidth);const bitmap=await createImageBitmap(video,{resizeWidth:Math.round(video.videoWidth*ratio),resizeHeight:Math.round(video.videoHeight*ratio),resizeQuality:'low'});const id=(this.seq||0)+1;this.seq=id;return await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{this.pending=null;reject(Error('Tracking timeout'))},2000);this.pending={id,resolve,reject,timer};try{this.worker.postMessage({type:'frame',bitmap,timestamp,id},[bitmap])}catch(e){clearTimeout(timer);this.pending=null;bitmap.close();reject(e)}})}finally{this.busy=false}}
}
